          "সেই মুখটি এক অদ্ভুত নিষ্ঠুর হাসিতে উদ্ভাসিত হয়ে উঠল। সে ধীরপায়ে এগিয়ে এসে বলল, \"মানুষ যাকে মৃত্যু মনে করে, তা কখনো কখনো কেবল দীর্ঘ এক প্রস্তুতি মাত্র। তোমাদের সুখের প্রাসাদ গুঁড়িয়ে দেওয়ার জন্যই আমি মৃত্যুর ওপার থেকে ফিরে এসেছি।\"",
          "তখনই পেছন থেকে স্মার্টফোনে এবং শফিক সাহেব ছুটে এলো। এই আকস্মিক মুখোমুখি সাক্ষাতে পুরো অতীত এক নিমেষে তাদের চোখের সামনে ভেসে উঠল। যে মানুষটিকে এতদিন সবাই বন্ধু অথবা শুভাকাঙ্ক্ষী মনে করেছিল, আসলে সেই ছিল সমস্ত চক্রান্ত ও ধ্বংসের মূল পরিকল্পনাকারী!",
